<?php
namespace Modules\Ran\Services;
use DomainException;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\StockLot;use Modules\Ran\Entities\Stocktake;use Modules\Ran\Support\RanContext;
class StocktakeService {public function __construct(private NumberSequenceService $numbers,private InventoryService $inventory,private AuditService $audit){}
 public function create(array $data):Stocktake{return DB::transaction(function()use($data){$stocktake=Stocktake::create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),['stocktake_no'=>$this->numbers->next('stocktake',(int)$data['location_id']),'stocktake_date'=>$data['stocktake_date'],'status'=>'draft','notes'=>$data['notes']??null]));foreach($data['lines'] as $line){$lot=StockLot::findOrFail($line['stock_lot_id']);$stocktake->lines()->create(array_merge(RanContext::scope(['location_id'=>$data['location_id'],'store_id'=>$data['store_id']]),['stock_lot_id'=>$lot->id,'item_id'=>$lot->item_id,'system_quantity'=>$lot->quantity,'counted_quantity'=>$line['counted_quantity'],'quantity_variance'=>(float)$line['counted_quantity']-(float)$lot->quantity,'system_weight'=>$lot->net_weight,'counted_weight'=>$line['counted_weight'],'weight_variance'=>(float)$line['counted_weight']-(float)$lot->net_weight,'notes'=>$line['notes']??null]));}$this->audit->record('created',$stocktake);return $stocktake->load('lines.stockLot.item');});}
 public function post(Stocktake $stocktake):Stocktake{if($stocktake->status!=='draft')throw new DomainException('Only draft stocktakes can be posted.');return DB::transaction(function()use($stocktake){$stocktake->load('lines.stockLot');foreach($stocktake->lines as $line){if(abs((float)$line->quantity_variance)>0.000001||abs((float)$line->weight_variance)>0.000001)$this->inventory->adjust($line->stockLot,(float)$line->quantity_variance,(float)$line->weight_variance,'Stocktake '.$stocktake->stocktake_no);}$stocktake->update(['status'=>'posted','posted_by'=>RanContext::userId(),'posted_at'=>now()]);$this->audit->record('posted',$stocktake);return $stocktake;});}}
